drop function regional_trends(text,text);
create function regional_trends(region text default '',lang text default 'en',category_name text default '')returns table(tag text,score numeric)language sql stable security invoker set search_path=public as $$
with unique_mentions as(select distinct ph.hashtag_id,p.author_id from post_hashtags ph join posts p on p.id=ph.post_id where p.created_at>now()-interval '24 hours'and p.language=lang and(region=''or p.city=region or p.state=region)and(category_name=''or exists(select 1 from post_topics pt join topics t on t.id=pt.topic_id where pt.post_id=p.id and t.category=category_name)))select h.name,sum(least(1.0,extract(epoch from(now()-u.created_at))/604800))::numeric from unique_mentions m join hashtags h on h.id=m.hashtag_id join profiles u on u.id=m.author_id where not u.suspended group by h.name order by 2 desc limit 20$$;
